RegistrationCompanyDetails = {
    init: async function (app, container, data) {
        console.log("RegistrationCompanyDetails.init called");

        app = app || session.app;
        container = $(container || '.component[name="RegistrationCompanyDetails"]');
        data = data || {};

        try {
            if (!container.length) {
                throw new Error(
                    "RegistrationCompanyDetails container was not found."
                );
            }

            const viewModel =
                typeof data.get === "function" &&
                typeof data.set === "function"
                    ? data
                    : kendo.observable({
                        CompanyName: data.CompanyName || "",
                        CompanyTaxReference:
                            data.CompanyTaxReference || "",
                        CompanyClientReference:
                            data.CompanyClientReference || "",
                        Perspective: data.Perspective || "",
                        CompanyAddressLine1:
                            data.CompanyAddressLine1 || "",
                        CompanyAddressLine2:
                            data.CompanyAddressLine2 || "",
                        CompanyRegion: data.CompanyRegion || "",
                        CompanyCounty: data.CompanyCounty || "",
                        CompanyPostcode: data.CompanyPostcode || "",
                        CompanyCountryCode:
                            data.CompanyCountryCode || "",
                        RequestedFundingType:
                            data.RequestedFundingType || ""
                    });

            const $select =
                $('select[name="CompanyCountryCode"]', container);

            if (!$select.length) {
                throw new Error(
                    'No select[name="CompanyCountryCode"] was found.'
                );
            }

            const countries = await api.get("B2B/Country");

            if (!countries || !Array.isArray(countries.value)) {
                throw new Error(
                    "B2B/Country did not return a value array."
                );
            }

            kendo.unbind(container);

            $select.empty();
            $select.append(new Option("", ""));

            countries.value.forEach(function (country) {
                $select.append(
                    new Option(country.Name, country.Id)
                );
            });

            kendo.bind(container, viewModel);
            container.data("model", viewModel);

            $select.val(
                viewModel.get("CompanyCountryCode") || ""
            );

            $select
                .off("change.registrationCompanyDetails")
                .on(
                    "change.registrationCompanyDetails",
                    function () {
                        viewModel.set(
                            "CompanyCountryCode",
                            $(this).val()
                        );
                    }
                );

            let validator =
                container.data("kendoValidator");

            if (!validator) {
                validator = container
                    .kendoValidator({
                        validateOnBlur: true
                    })
                    .data("kendoValidator");
            }

            container.data("validator", validator);

            if (!container.data("kendoTooltip")) {
                container.kendoTooltip({
                    filter: ".funding-tooltip",
                    position: "top",
                    showOn: "mouseenter",
                    width: 250,
                    content: function (e) {
                        return e.target.attr("title") || "";
                    }
                });
            }

            console.log(
                "Company details: loaded",
                countries.value.length,
                "countries"
            );
        } catch (err) {
            console.error(
                "Company details initialisation failed:",
                err
            );

            throw err;
        }
    }
};
